#include <zephyr/posix/time.h>
#include <zephyr/kernel.h>
#include <zephyr/timing/timing.h>
#include <errno.h>

#ifdef CONFIG_64BIT_TIME
#define NSEC_PER_SEC 1000000000LL
#else
#define NSEC_PER_SEC 1000000000L
#endif

int clock_getres(clockid_t clock_id, struct timespec *res)
{
    if (res == NULL) {
        /* POSIX says: If res is NULL, the resolution of the clock is not returned. */
        return 0;
    }

    switch (clock_id) {
    case CLOCK_MONOTONIC:
    case CLOCK_MONOTONIC_RAW:
    case CLOCK_REALTIME:
    case CLOCK_BOOTTIME:
        /*
         * Zephyr's kernel timer is based on system clock ticks.
         * The resolution is 1 / CONFIG_SYS_CLOCK_TICKS_PER_SEC.
         * Convert this to nanoseconds.
         */
        res->tv_sec = 0;
        res->tv_nsec = NSEC_PER_SEC / CONFIG_SYS_CLOCK_TICKS_PER_SEC;
        if (res->tv_nsec == 0) {
            /* If ticks per sec is very high, nsec might be 0.
             * In that case, the resolution is less than 1ns,
             * so report 1ns.
             */
            res->tv_nsec = 1;
        }
        break;
    case CLOCK_PROCESS_CPUTIME_ID:
    case CLOCK_THREAD_CPUTIME_ID:
        /* CPU time clocks are not yet implemented with specific resolution */
        res->tv_sec = 0;
        res->tv_nsec = NSEC_PER_SEC / CONFIG_SYS_CLOCK_TICKS_PER_SEC;
        if (res->tv_nsec == 0) {
            res->tv_nsec = 1;
        }
        break;
    default:
        errno = EINVAL;
        return -1;
    }

    return 0;
}

int clock_gettime(clockid_t clock_id, struct timespec *ts)
{
    if (ts == NULL) {
        errno = EINVAL;
        return -1;
    }

    switch (clock_id) {
    case CLOCK_MONOTONIC:
    case CLOCK_MONOTONIC_RAW:
    case CLOCK_BOOTTIME:
        {
            k_timeout_t uptime = k_uptime_get_32();
            ts->tv_sec = uptime / 1000;
            ts->tv_nsec = (uptime % 1000) * 1000000;
        }
        break;
    case CLOCK_REALTIME:
        {
            k_timeout_t uptime = k_uptime_get_32();
            /* For simplicity, assume realtime is same as monotonic for now */
            ts->tv_sec = uptime / 1000;
            ts->tv_nsec = (uptime % 1000) * 1000000;
        }
        break;
    case CLOCK_PROCESS_CPUTIME_ID:
    case CLOCK_THREAD_CPUTIME_ID:
        /* Not yet implemented */
        errno = EINVAL;
        return -1;
    default:
        errno = EINVAL;
        return -1;
    }

    return 0;
}

int clock_settime(clockid_t clock_id, const struct timespec *ts)
{
    /* Setting CLOCK_REALTIME is not supported directly in Zephyr kernel */
    errno = EINVAL;
    return -1;
}

int nanosleep(const struct timespec *rqtp, struct timespec *rmtp)
{
    if (rqtp == NULL) {
        errno = EINVAL;
        return -1;
    }

    if (rqtp->tv_sec < 0 || rqtp->tv_nsec < 0 || rqtp->tv_nsec >= NSEC_PER_SEC) {
        errno = EINVAL;
        return -1;
    }

    k_sleep(K_NSEC(rqtp->tv_sec * NSEC_PER_SEC + rqtp->tv_nsec));

    if (rmtp != NULL) {
        rmtp->tv_sec = 0;
        rmtp->tv_nsec = 0;
    }

    return 0;
}
